create table RB_LIMIT_CTRL_CUSTOM_INFO (CLIENT_NO VARCHAR(22) not null  ,LIMIT_SCENE_NO VARCHAR(50) not null  ,CHECK_OBJ_VAL VARCHAR(50) not null  ,CTRL_ITEM_TYPE VARCHAR(1) null  ,LIMIT_CTRL_NUM INT null  ,LIMIT_CTRL_AMT DECIMAL(38,2) null  ,TEMP_LIMIT_FLAG VARCHAR(1) null  ,EFFECT_DATE TIMESTAMP(3) null  ,EXPIRE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,UPDATE_DATE TIMESTAMP(3) null  ,CREATE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(CLIENT_NO,LIMIT_SCENE_NO,CHECK_OBJ_VAL));